#include <atcoder/all>
#include <bits/stdc++.h>
int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  int n, q;
  if (!(std::cin >> n >> q)) return 0;
  atcoder::fenwick_tree<long long> fw(n);
  for (int i = 0; i < n; ++i) {
    long long a; std::cin >> a; fw.add(i, a);
  }
  for (int i = 0; i < q; ++i) {
    int t, a; long long b;
    std::cin >> t >> a >> b;
    if (t == 0) fw.add(a, b);
    else std::cout << fw.sum(a, static_cast<int>(b)) << '\n';
  }
}

